#!/usr/bin/env python3
# -*- coding: utf-8 -*-

# Author: Rensc
# Date: 2026-08-09
# Version: dev001
# Function: Compare shared and condition-specific SeRP peaks between two samples.
# Input: Two SeRP peak tables generated by serp_peak.
# Output: Overlap summaries, shared peak clusters, relationships, and condition-specific peaks.

"""Command-line entry point for pairwise SeRP peak-overlap analysis."""

from __future__ import annotations

import argparse
from argparse import Namespace
from collections.abc import Sequence
from pathlib import Path

from utils.ribo.ArgsParser import (
    args_print,
    complete_print,
    file_check,
    now_time,
    result_print,
    step_print,
    title_print,
)
from utils.serp.Overlap import PeakOverlapAnalyzer
from utils.serp.OverlapOutput import SeRPOverlapOutput


def _build_parser() -> argparse.ArgumentParser:
    """Build the command-line argument parser."""
    parser = argparse.ArgumentParser(
        formatter_class=argparse.RawDescriptionHelpFormatter,
        description=(
            "Compare transcript-level SeRP peak intervals between two biological "
            "conditions and classify shared versus condition-specific peaks."
        ),
        epilog=(
            "Peak coordinates are transcript-relative codon positions. By default, "
            "all called peaks in *_peaks.txt are compared. Use --max-fdr only when "
            "BHFDR-based filtering is explicitly required."
        ),
    )

    required_group = parser.add_argument_group("Required arguments")
    required_group.add_argument(
        "-a",
        "--peak-a",
        "-m",
        "--mock",
        dest="peak_a",
        required=True,
        type=str,
        help="Peak table for condition A. Legacy -m/--mock aliases are supported.",
    )
    required_group.add_argument(
        "-b",
        "--peak-b",
        "-f",
        "--flag",
        dest="peak_b",
        required=True,
        type=str,
        help="Peak table for condition B. Legacy -f/--flag aliases are supported.",
    )
    required_group.add_argument(
        "-o",
        "--output",
        dest="output",
        required=True,
        type=str,
        help="Output prefix for all overlap-analysis tables.",
    )

    sample_group = parser.add_argument_group("Sample labels")
    sample_group.add_argument(
        "--name-a",
        dest="name_a",
        default=None,
        type=str,
        help="Condition-A label. Default: peak-A filename stem.",
    )
    sample_group.add_argument(
        "--name-b",
        dest="name_b",
        default=None,
        type=str,
        help="Condition-B label. Default: peak-B filename stem.",
    )

    overlap_group = parser.add_argument_group("Overlap criteria")
    overlap_group.add_argument(
        "--min-overlap",
        dest="min_overlap",
        default=6,
        type=int,
        help=(
            "Minimum inclusive overlap in codon positions for a shared relationship "
            "(default: %(default)s)."
        ),
    )
    overlap_group.add_argument(
        "--min-reciprocal",
        dest="min_reciprocal",
        default=0.5,
        type=float,
        help=(
            "Minimum overlap fraction required for both peaks "
            "(default: %(default)s)."
        ),
    )
    overlap_group.add_argument(
        "--interval",
        dest="interval",
        choices=["core", "extended"],
        default="core",
        help=(
            "Compare core peak_start/peak_end or extended collision_start/"
            "collision_end intervals (default: %(default)s)."
        ),
    )

    filter_group = parser.add_argument_group("Optional peak filtering")
    filter_group.add_argument(
        "--max-fdr",
        dest="max_fdr",
        default=None,
        type=float,
        help=(
            "Optional maximum BHFDR before overlap analysis. Peaks with missing "
            "BHFDR are excluded only when this option is used."
        ),
    )

    return parser


def _default_sample_name(file_name: str) -> str:
    """Derive a concise condition name from one peak-table filename."""
    name = Path(file_name).name
    suffixes = [
        "_peaks.txt",
        ".peaks.txt",
        "_sig_peaks.txt",
        ".txt",
        ".tsv",
    ]
    for suffix in suffixes:
        if name.endswith(suffix):
            return name[: -len(suffix)]
    return Path(name).stem


def _validate_args(args: Namespace) -> None:
    """Validate command-line arguments."""
    file_check(args.peak_a, args.peak_b)
    if args.min_overlap < 1:
        raise ValueError("--min-overlap must be >= 1 codon position.")
    if not 0 <= args.min_reciprocal <= 1:
        raise ValueError("--min-reciprocal must be within [0, 1].")
    if args.name_a == args.name_b:
        raise ValueError("--name-a and --name-b must be different condition labels.")
    for label in (args.name_a, args.name_b):
        if "\t" in label or "\n" in label or "\r" in label:
            raise ValueError("Sample labels cannot contain tabs or line breaks.")
    if args.max_fdr is not None and not 0 <= args.max_fdr <= 1:
        raise ValueError("--max-fdr must be within [0, 1].")


def _parse_args(argv: Sequence[str] | None = None) -> Namespace:
    """Parse, validate, and print command-line arguments."""
    parser = _build_parser()
    args = parser.parse_args(argv)

    if args.name_a is None:
        args.name_a = _default_sample_name(args.peak_a)
    if args.name_b is None:
        args.name_b = _default_sample_name(args.peak_b)

    _validate_args(args)
    args_print(args)
    return args


def main(argv: Sequence[str] | None = None) -> None:
    """Command-line entry point for serp_overlap."""
    now_time()
    title_print("Compare shared and condition-specific SeRP peaks.")
    step_print(1, "Checking the input arguments.")
    args = _parse_args(argv)

    workflow = PeakOverlapAnalyzer(
        peak_a_file=args.peak_a,
        peak_b_file=args.peak_b,
        name_a=args.name_a,
        name_b=args.name_b,
        output_prefix=args.output,
        min_overlap=args.min_overlap,
        min_reciprocal=args.min_reciprocal,
        interval_mode=args.interval,
        max_fdr=args.max_fdr,
    )

    step_print(2, "Import and validate called peak tables.")
    workflow.load_peaks()

    step_print(3, "Build transcript-level overlap relationships and shared clusters.")
    workflow.analyze()

    step_print(4, "Write shared, specific, relationship, and length-summary tables.")
    output = SeRPOverlapOutput(workflow)
    output.write_results()

    result_print(workflow.result_counts())
    complete_print()
    now_time()


if __name__ == "__main__":
    main()